import { type FormEvent, useEffect, useState } from "react";
import { ArrowDown, ArrowUp, Pencil, Trash2 } from "lucide-react";
import { api } from "../lib/ideas";
import type { Block } from "../lib/blocks";

function Markdown({ html }: { html: string }) {
  // body_html is generated by todo_v2.markdown, which escapes every user string
  // and allowlists link protocols. Never put the raw body in this HTML sink.
  return <div className="min-w-0 whitespace-normal text-sm [overflow-wrap:anywhere] [&_p]:mb-2 [&_p:last-child]:mb-0 [&_ul]:list-disc [&_ul]:pl-5 [&_pre]:overflow-auto [&_pre]:rounded [&_pre]:bg-panel [&_pre]:p-3 [&_code]:font-mono [&_a]:text-accent [&_a]:underline [&_h1]:font-semibold [&_h2]:font-semibold [&_h3]:font-semibold"
    dangerouslySetInnerHTML={{ __html: html }} />;
}

export default function BlocksEditor({ owner, id, onChange }: {
  owner: "tasks" | "ideas"; id: number; onChange?: () => void;
}) {
  const path = `/${owner}/${id}/blocks`;
  const [blocks, setBlocks] = useState<Block[] | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [kind, setKind] = useState<Block["kind"]>("note");
  const [body, setBody] = useState("");
  const [editing, setEditing] = useState<number | null>(null);
  const [draft, setDraft] = useState("");
  async function load() {
    try { setBlocks(await api<Block[]>(path)); setError(""); }
    catch (error) { setError((error as Error).message); }
  }
  useEffect(() => {
    let live = true;
    setBlocks(null); setError(""); setEditing(null);
    api<Block[]>(path).then((rows) => { if (live) setBlocks(rows); })
      .catch((error: Error) => { if (live) setError(error.message); });
    return () => { live = false; };
  }, [path]);
  async function mutate(action: () => Promise<unknown>, after?: () => void) {
    if (busy) return;
    setBusy(true); setError("");
    try {
      await action(); after?.();
      await load(); onChange?.();
    } catch (error) { setError((error as Error).message); }
    finally { setBusy(false); }
  }
  function add(event: FormEvent) {
    event.preventDefault();
    if (body.trim()) void mutate(() => api(path, "POST", { kind, body }), () => setBody(""));
  }
  function move(index: number, direction: number) {
    if (!blocks) return;
    const ids = blocks.map((block) => block.id);
    [ids[index], ids[index + direction]] = [ids[index + direction], ids[index]];
    void mutate(() => api(path + "/order", "PUT", { ids }));
  }
  return <section aria-label="Notes and checklist" className="space-y-3">
    <div>
      <h2 className="section-title">Notes &amp; checklist</h2>
      <p className="mt-1 text-xs text-muted">Markdown notes and small steps. Checklist items don’t count toward project progress.</p>
    </div>
    {error && <p role="alert" className="text-sm text-danger">{error} <button className="btn btn-quiet btn-sm" disabled={busy} onClick={load}>Retry</button></p>}
    {blocks === null ? !error && <p role="status" className="text-sm text-muted">Loading blocks…</p> : <>
      {blocks.length > 0 ? <ol className="well divide-y divide-edge">
        {blocks.map((block, index) => <li key={block.id} className="p-3 sm:p-4">
          {editing === block.id ? <form className="space-y-2" onSubmit={(event) => {
            event.preventDefault();
            void mutate(() => api(`/blocks/${block.id}`, "PATCH", { body: draft }), () => setEditing(null));
          }}>
            <label className="block"><span className="eyebrow mb-1 block">Edit {block.kind === "note" ? "note" : "checklist item"}</span>
              <textarea autoFocus className="field w-full" rows={3} value={draft} disabled={busy} onChange={(event) => setDraft(event.target.value)} /></label>
            <div className="flex gap-2">
              <button className="btn btn-primary btn-sm" disabled={busy}>Save block</button>
              <button type="button" className="btn btn-quiet btn-sm" disabled={busy} onClick={() => setEditing(null)}>Cancel</button>
            </div>
          </form> : <>
            <div className="flex items-start gap-3">
              {block.kind === "subtask" && <input type="checkbox" className="mt-1 h-4 w-4 shrink-0 cursor-pointer"
                aria-label={`Check off ${block.body}`} checked={block.done} disabled={busy || editing !== null}
                onChange={() => void mutate(() => api(`/blocks/${block.id}`, "PATCH", { done: !block.done }))} />}
              <div className={`min-w-0 flex-1 ${block.done ? "text-muted" : ""}`}>
                <span className="eyebrow mb-2 block">{block.kind === "note" ? "Note" : block.done ? "Checklist · done" : "Checklist"}</span>
                <Markdown html={block.body_html} />
              </div>
            </div>
            <div className="mt-2 flex flex-wrap justify-end gap-1">
              <button className="btn btn-quiet btn-sm" aria-label={`Move block ${index + 1} up`} disabled={busy || editing !== null || index === 0} onClick={() => move(index, -1)}><ArrowUp size={14} /></button>
              <button className="btn btn-quiet btn-sm" aria-label={`Move block ${index + 1} down`} disabled={busy || editing !== null || index === blocks.length - 1} onClick={() => move(index, 1)}><ArrowDown size={14} /></button>
              <button className="btn btn-quiet btn-sm" aria-label={`Edit block ${index + 1}`} disabled={busy || editing !== null} onClick={() => { setDraft(block.body); setEditing(block.id); }}><Pencil size={14} /><span>Edit</span></button>
              <button className="btn btn-quiet btn-sm" aria-label={`Delete block ${index + 1}`} disabled={busy || editing !== null} onClick={() => void mutate(() => api(`/blocks/${block.id}`, "DELETE"))}><Trash2 size={14} /><span>Delete</span></button>
            </div>
          </>}
        </li>)}
      </ol> : <p className="text-sm text-muted">Add a note or a small step below.</p>}
      <form className="well space-y-3 p-3 sm:p-4" onSubmit={add}>
        <label className="block"><span className="eyebrow mb-1 block">New block</span>
          <select className="field w-full sm:w-auto" value={kind} disabled={busy} onChange={(event) => setKind(event.target.value as Block["kind"])}>
            <option value="note">Note</option><option value="subtask">Checklist item</option>
          </select></label>
        <label className="block"><span className="eyebrow mb-1 block">Markdown</span>
          <textarea className="field w-full" rows={2} placeholder={kind === "note" ? "Keep a useful detail…" : "One small step…"}
            value={body} disabled={busy} onChange={(event) => setBody(event.target.value)} /></label>
        <button className="btn btn-primary btn-sm" disabled={busy || !body.trim()}>Add {kind === "note" ? "note" : "checklist item"}</button>
      </form>
    </>}
  </section>;
}
